# First matching word wins when the admin hasn't picked an icon.
_GUESSES = [
    (("network", "wifi", "wi-fi", "lan", "router", "internet"), "wifi"),
    (("security", "secure", "firewall", "antivirus", "cyber"), "shield"),
    (("backup", "data", "database", "storage"), "database"),
    (("email", "mail", "domain"), "email"),
    (("cloud", "hosting", "server"), "cloud"),
    (("web", "website", "software", "app", "develop"), "code"),
    (("mobile", "android", "ios", "phone"), "mobile"),
    (("cctv", "camera", "video"), "camera"),
    (("support", "maintenance", "repair", "fix"), "support"),
    (("ai", "machine learning", "automation"), "ai"),
    (("ecommerce", "e-commerce", "shop", "store"), "cart"),
    (("analytics", "report", "intelligence", "marketing", "seo"), "chart"),
    (("training", "lms", "course", "school"), "education"),
    (("bank", "finance", "accounting", "erp"), "bank"),
    (("consult", "strategy", "business"), "briefcase"),
    (("staff", "team", "outsourc"), "users"),
    (("hardware", "pc", "computer", "laptop"), "chip"),
]


def service_icon(service: dict | None) -> str:
    """SVG path data for a service's icon."""
    if not service:
        return ICONS["idea"]
    chosen = (service.get("icon") or "").strip()
    if chosen in ICONS:
        return ICONS[chosen]
    text = f" {service.get('title') or ''} {service.get('category') or ''} ".lower()
    for words, name in _GUESSES:
        if any(w in text for w in words):
            return ICONS[name]
    return ICONS["idea"]
